package es.upm.etsisi.poo;


public abstract class Usuario implements IDatosUsuario {
	private String nick;
	private String nombre;
	private String correo;
	private String contrasenaCifrada;



    public Usuario(String nick, String nombre, String correo, String contrasena) {
        this.nick = nick;
        this.nombre = nombre;
        this.correo = correo;
        this.contrasenaCifrada = cifrarContrasena(contrasena);
    }
	
	public String getNick() {
        return this.nick;
	}
	
	public String getNombre() {
        return this.nombre;
	
	}
	
	public String getCorreo() {
        return this.correo;
	
	}
    public String getContrasenaCifrada() {
        return contrasenaCifrada;
    }
	
	public void setContrasena(String nuevaContrasena) {
        this.contrasenaCifrada = cifrarContrasena(nuevaContrasena);
	}
	
	public boolean verificarContrasena(String contrasena) {
        String intentoCifrado = cifrarContrasena(contrasena);
        return intentoCifrado.equals(this.contrasenaCifrada);
	}
	
	private String cifrarContrasena(String contrasenia) {
         try {
                java.security.MessageDigest md = java.security.MessageDigest.getInstance("SHA-256");
                byte[] hash = md.digest(contrasenia.getBytes(java.nio.charset.StandardCharsets.UTF_8));
                StringBuilder hexString = new StringBuilder();
                for (byte b : hash) {
                    String hex = Integer.toHexString(0xff & b);
                    if (hex.length() == 1) hexString.append('0');
                    hexString.append(hex);
                }
                return hexString.toString();
            } catch (Exception e) {
                return contrasenia; // Si falla por algún motivo, devuelve el texto original como plan de respaldo
            }
    }

    @Override
    public String toString() {
        return nick + ";" + nombre + ";" + correo + ";" + contrasenaCifrada;
    }
    protected void setContrasenaCifradaDirectamente(String contrasenaCifrada) {
        this.contrasenaCifrada = contrasenaCifrada;
    }


	
}
